export interface CanvasSize {
  readonly width: number;
  readonly height: number;
}

export interface Widget {
  readonly id: string;
  readonly x: number;
  readonly y: number;
  readonly width: number;
  readonly height: number;
  readonly selected: boolean;
}

export type WidgetCommand =
  | { readonly type: "move"; readonly x: number; readonly y: number }
  | { readonly type: "resize"; readonly width: number; readonly height: number }
  | { readonly type: "select"; readonly selected: boolean };

function finite(value: number): boolean {
  return Number.isFinite(value);
}

function validate(widget: Widget, canvas: CanvasSize): void {
  if (!finite(canvas.width) || !finite(canvas.height) || canvas.width <= 0 || canvas.height <= 0) {
    throw new RangeError("Canvas dimensions must be finite and positive");
  }
  if (![widget.x, widget.y, widget.width, widget.height].every(finite) || widget.width <= 0 || widget.height <= 0) {
    throw new RangeError("Widget geometry must be finite with positive dimensions");
  }
}

function clamp(value: number, low: number, high: number): number {
  return Math.min(Math.max(value, low), high);
}

export function applyWidgetCommand(widget: Widget, command: WidgetCommand, canvas: CanvasSize): Widget {
  validate(widget, canvas);
  if (command.type === "select") {
    return { ...widget, selected: command.selected };
  }
  if (command.type === "move") {
    if (!finite(command.x) || !finite(command.y)) throw new RangeError("Move coordinates must be finite");
    return {
      ...widget,
      x: clamp(command.x, 0, canvas.width),
      y: clamp(command.y, 0, Math.max(0, canvas.height - widget.height))
    };
  }
  if (!finite(command.width) || !finite(command.height)) throw new RangeError("Resize dimensions must be finite");
  const width = clamp(command.width, Math.min(20, canvas.width), canvas.width);
  const height = clamp(command.height, Math.min(20, canvas.height), canvas.height);
  return {
    ...widget,
    width,
    height,
    x: clamp(widget.x, 0, canvas.width - width),
    y: clamp(widget.y, 0, canvas.height - height)
  };
}

