import { applyWidgetCommand, CanvasSize, Widget, WidgetCommand } from "./solution";

function assert(condition: boolean, message: string): void {
  if (!condition) throw new Error(message);
}
function equal(actual: unknown, expected: unknown, message: string): void {
  if (!Object.is(actual, expected)) throw new Error(`${message}: expected ${String(expected)}, got ${String(actual)}`);
}
function rangeError(fn: () => unknown, message: string): void {
  try { fn(); } catch (error) { if (error instanceof RangeError) return; throw new Error(`${message}: wrong error`); }
  throw new Error(`${message}: did not throw`);
}

const canvas: CanvasSize = { width: 100, height: 80 };
const widget: Widget = { id: "", x: 30, y: 25, width: 40, height: 30, selected: false };
const move: WidgetCommand = { type: "move", x: 95, y: -10 };
const moved = applyWidgetCommand(widget, move, canvas);
equal(moved.id, "", "empty id preserved");
equal(moved.x, 60, "move clamps right");
equal(moved.y, 0, "move clamps top");
equal(moved.width, 40, "move preserves width");
equal(moved.height, 30, "move preserves height");
equal(moved.selected, false, "move preserves selection");
assert(moved !== widget, "move returns a fresh widget");
equal(widget.x, 30, "move does not mutate x");
equal(widget.y, 25, "move does not mutate y");
equal(move.x, 95, "move command is not mutated");

const boundaryMove = applyWidgetCommand(widget, { type: "move", x: 60, y: 50 }, canvas);
equal(boundaryMove.x, 60, "exact right boundary accepted");
equal(boundaryMove.y, 50, "exact bottom boundary accepted");

const resized = applyWidgetCommand(widget, { type: "resize", width: 500, height: 5 }, canvas);
equal(resized.width, 100, "resize clamps to canvas width");
equal(resized.height, 20, "resize clamps to minimum height");
equal(resized.x, 0, "resize reclamps x");
equal(resized.y, 25, "resize retains valid y");
equal(widget.width, 40, "resize does not mutate input");

const exactResize = applyWidgetCommand(widget, { type: "resize", width: 20, height: 80 }, canvas);
equal(exactResize.width, 20, "minimum size accepted");
equal(exactResize.height, 80, "canvas-sized height accepted");
equal(exactResize.y, 0, "position clamped after resize");

const selected = applyWidgetCommand(widget, { type: "select", selected: true }, canvas);
equal(selected.selected, true, "selection changes");
equal(selected.x, 30, "selection preserves x");
equal(selected.y, 25, "selection preserves y");
equal(selected.width, 40, "selection preserves width");
assert(selected !== widget, "selection returns a fresh widget");

rangeError(() => applyWidgetCommand(widget, { type: "move", x: 0, y: 0 }, { width: 0, height: 80 }), "zero canvas width");
rangeError(() => applyWidgetCommand(widget, { type: "move", x: 0, y: 0 }, { width: 100, height: Infinity }), "non-finite canvas height");
rangeError(() => applyWidgetCommand(widget, { type: "move", x: NaN, y: 0 }, canvas), "non-finite move coordinate");
rangeError(() => applyWidgetCommand(widget, { type: "resize", width: 20, height: Infinity }, canvas), "non-finite resize dimension");
rangeError(() => applyWidgetCommand({ ...widget, width: 0 }, { type: "select", selected: true }, canvas), "zero existing width");
rangeError(() => applyWidgetCommand({ ...widget, height: NaN }, { type: "select", selected: true }, canvas), "non-finite existing height");

